class Trie:
    def __init__(self):
        self.words = set()              # 用集合存储所有完整单词

    def insert(self, word):
        self.words.add(word)            # O(L) 哈希插入

    def search(self, word):
        return word in self.words       # 完整匹配一次哈希查询

    def startsWith(self, prefix):
        # 集合不含前缀结构信息，只能全量扫描逐词比较
        return any(w.startswith(prefix) for w in self.words)

class Trie:
    def __init__(self):
        self.words = set()              # 完整单词集合
        self.prefixes = set()           # 所有可能前缀集合

    def insert(self, word):
        self.words.add(word)
        for k in range(1, len(word) + 1):
            self.prefixes.add(word[:k])  # 长度 1..L 的全部前缀（含原词）

    def search(self, word):
        return word in self.words       # O(L) 哈希查询

    def startsWith(self, prefix):
        return prefix in self.prefixes  # O(L) 哈希查询

class Trie:
    def __init__(self):
        self.children = {}      # 嵌套字典实现树节点：键为字符，值为下一层子节点
        self.is_end = False     # 标记从根到该节点的路径是否构成一个完整单词

    def insert(self, word):
        node = self
        for ch in word:
            if ch not in node.children:
                node.children[ch] = Trie()   # 缺少对应分支就新建子节点
            node = node.children[ch]         # 沿单词逐字符下行
        node.is_end = True                   # 单词末尾打上结束标记

    def _walk(self, s):
        node = self
        for ch in s:                # 沿字符串下行，返回末节点；走不通返回 None
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.is_end   # 完整单词：路径存在且是结尾

    def startsWith(self, prefix):
        return self._walk(prefix) is not None     # 前缀：只要路径存在即可

