class Trie {
public:
    void insert(string word) {
        Trie* node = this;
        for (char ch : word) {
            if (!node->children.count(ch))  // 缺少对应分支就新建子节点
                node->children[ch] = new Trie();
            node = node->children[ch];      // 沿单词逐字符下行
        }
        node->isEnd = true;                 // 单词末尾打上结束标记
    }

    bool search(string word) {
        Trie* node = walk(word);
        return node != nullptr && node->isEnd;  // 完整单词：路径存在且是结尾
    }

    bool startsWith(string prefix) {
        return walk(prefix) != nullptr;     // 前缀：只要路径存在即可
    }

private:
    // 嵌套映射实现树节点：键为字符，值为下一层子节点
