// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（操作数）
//   接下来 n 行：每行 "op word"，op ∈ insert / search / startsWith（空格分隔）
// 输出格式：n 行，每行对应操作结果；insert 输出 null，查询输出 true / false
#include <iostream>
#include <string>
#include <unordered_map>

using namespace std;

struct Trie {
    unordered_map<char, Trie*> children;  // 字符 -> 子节点
    bool isEnd = false;                   // 是否有单词在此结束

    void insert(const string& word) {
        Trie* node = this;
        for (char ch : word) {
            if (!node->children.count(ch))  // 缺分支就新建
                node->children[ch] = new Trie();
            node = node->children[ch];
        }
        node->isEnd = true;  // 末尾打结束标记
    }

    // 沿字符串下行，走不通返回 nullptr
    Trie* walk(const string& s) {
        Trie* node = this;
        for (char ch : s) {
            auto it = node->children.find(ch);
            if (it == node->children.end()) return nullptr;
            node = it->second;
        }
        return node;
    }

    bool search(const string& word) {
        Trie* node = walk(word);
        return node != nullptr && node->isEnd;
    }

    bool startsWith(const string& prefix) {
        return walk(prefix) != nullptr;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    Trie trie;
    for (int i = 0; i < n; ++i) {
        string op, word;
        cin >> op >> word;  // 每行 "op word"
        if (op == "insert") {
            trie.insert(word);
            cout << "null" << '\n';
        } else if (op == "search") {
            cout << (trie.search(word) ? "true" : "false") << '\n';
        } else {  // startsWith
            cout << (trie.startsWith(word) ? "true" : "false") << '\n';
        }
    }
    return 0;
}

