var Trie = function () {
  this.children = new Map();  // 键为字符，值为下一层子节点
  this.isEnd = false;         // 标记从根到该节点的路径是否构成一个完整单词
};

/**
 * @param {string} word
 * @return {void}
 */
Trie.prototype.insert = function (word) {
  let node = this;
  for (const ch of word) {
    if (!node.children.has(ch)) {  // 缺少对应分支就新建子节点
      node.children.set(ch, new Trie());
    }
    node = node.children.get(ch);  // 沿单词逐字符下行
  }
  node.isEnd = true;               // 单词末尾打上结束标记
};

/**
 * 沿字符串下行，返回末节点；走不通返回 null
 * @param {string} s
 * @return {Trie|null}
 */
Trie.prototype._walk = function (s) {
  let node = this;
  for (const ch of s) {
    if (!node.children.has(ch)) return null;
    node = node.children.get(ch);
  }
  return node;
};

/**
 * 完整单词匹配：路径存在且是结尾
 * @param {string} word
 * @return {boolean}
 */
Trie.prototype.search = function (word) {
  const node = this._walk(word);
  return node !== null && node.isEnd;
};

/**
 * 前缀匹配：只要路径存在即可
 * @param {string} prefix
 * @return {boolean}
 */
Trie.prototype.startsWith = function (prefix) {
  return this._walk(prefix) !== null;
};

