// Trie 节点：children 存 字符 -> 子节点 映射，isEnd 标记单词结尾
type Trie struct {
	children map[byte]*Trie
	isEnd    bool
}

// Constructor 返回初始化好的前缀树根节点（children 必须显式初始化，零值 map 不可写入）
func Constructor() Trie {
	return Trie{children: map[byte]*Trie{}}
}

// Insert 沿单词逐字符下行，缺分支就新建，末尾打结束标记
func (t *Trie) Insert(word string) {
	node := t
	for i := 0; i < len(word); i++ {
		ch := word[i]
		if _, ok := node.children[ch]; !ok { // 缺少对应分支就新建子节点
			node.children[ch] = &Trie{children: map[byte]*Trie{}}
		}
		node = node.children[ch] // 沿单词逐字符下行
	}
	node.isEnd = true // 单词末尾打上结束标记
}

// walk 沿字符串下行，返回末节点；走不通返回 nil
func (t *Trie) walk(s string) *Trie {
	node := t
	for i := 0; i < len(s); i++ {
		child, ok := node.children[s[i]]
		if !ok {
			return nil
		}
		node = child
	}
	return node
}

// Search 完整单词匹配：路径存在且是结尾
func (t *Trie) Search(word string) bool {
	node := t.walk(word)
	return node != nil && node.isEnd
}

// StartsWith 前缀匹配：只要路径存在即可
func (t *Trie) StartsWith(prefix string) bool {
	return t.walk(prefix) != nil
}

