from collections import defaultdict

class WordDictionary:
    def __init__(self):
        self.groups = defaultdict(set)  # 长度 -> 该长度的所有单词

    def addWord(self, word):
        self.groups[len(word)].add(word)   # 等长是匹配的必要条件

    def search(self, word):
        for cand in self.groups.get(len(word), ()):
            # 逐字符比对：模式位 '.' 通配，其余必须相等
            if all(c == '.' or c == a for c, a in zip(word, cand)):
                return True
        return False

class WordDictionary:
    def __init__(self):
        self.children = {}      # 嵌套字典实现字典树：字符 -> 子节点
        self.is_end = False     # 是否有单词在此节点结束

    def addWord(self, word):
        node = self
        for ch in word:
            node = node.children.setdefault(ch, WordDictionary())  # 不存在则创建
        node.is_end = True

    def search(self, word):
        return self.dfs(word, 0, self)          # 从根节点开始逐字符匹配

    def dfs(self, word, i, node):
        if i == len(word):
            return node.is_end                  # 走完单词：必须是完整结尾才命中
        ch = word[i]
        if ch == '.':
            # 通配符：对所有子分支递归尝试，任一命中即真（any 短路剪枝）
            return any(self.dfs(word, i + 1, child)
                       for child in node.children.values())
        child = node.children.get(ch)
        return child is not None and self.dfs(word, i + 1, child)  # 单路下探

