}

// Constructor 返回初始化好的字典树根节点（children 必须显式初始化，零值 map 不可写入）
func Constructor() WordDictionary {
	return WordDictionary{children: map[byte]*WordDictionary{}}
}

// AddWord 沿单词逐字符下行，不存在则创建分支
func (this *WordDictionary) AddWord(word string) {
	node := this
	for i := 0; i < len(word); i++ {
		ch := word[i]
		if _, ok := node.children[ch]; !ok { // 不存在则创建分支
			node.children[ch] = &WordDictionary{children: map[byte]*WordDictionary{}}
		}
		node = node.children[ch]
	}
	node.isEnd = true
}

// Search 支持通配符 '.' 的搜索：从根节点开始逐字符匹配
func (this *WordDictionary) Search(word string) bool {
	return this.dfs(word, 0, this)
}

// dfs 逐字符下行：'.' 对所有子分支递归尝试（回溯），任一命中即真
func (this *WordDictionary) dfs(word string, i int, node *WordDictionary) bool {
	if i == len(word) {
		return node.isEnd // 走完单词：必须是完整结尾才算命中
	}
	if word[i] == '.' {
		for _, child := range node.children { // 枚举所有分支逐一尝试
			if this.dfs(word, i+1, child) {
				return true
			}
		}
		return false
	}
	child, ok := node.children[word[i]]
	return ok && this.dfs(word, i+1, child) // 单路下探
}

