    struct TrieNode {
        unordered_map<char, TrieNode*> children;
        string word;
    };

public:
    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {
        TrieNode* root = new TrieNode();
        for (const string& w : words) {  // 逐单词建 Trie
            TrieNode* node = root;
            for (char ch : w) {
                if (!node->children.count(ch))
                    node->children[ch] = new TrieNode();
                node = node->children[ch];
            }
            node->word = w;  // 结尾存完整单词，命中即收集
        }

        int m = board.size(), n = board[0].size();
        vector<string> ans;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                dfs(board, i, j, root, ans);  // 每个格子都尝试作为单词起点
            }
        }
        return ans;
    }

private:
    void dfs(vector<vector<char>>& board, int i, int j, TrieNode* parent,
             vector<string>& ans) {
        char ch = board[i][j];
        auto it = parent->children.find(ch);
        if (it == parent->children.end()) return;  // 当前字符在 Trie 上无路可走，剪枝

        TrieNode* node = it->second;
        if (!node->word.empty()) {  // 命中单词就收集；清空防止同一单词重复加入
            ans.push_back(node->word);
            node->word.clear();
        }
        board[i][j] = '#';  // 原地标记已访问
        int m = board.size(), n = board[0].size();
        const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (auto& d : dirs) {
            int x = i + d[0], y = j + d[1];
            if (x >= 0 && x < m && y >= 0 && y < n && board[x][y] != '#') {
                dfs(board, x, y, node, ans);  // 四方向继续与 Trie 同步下行
            }
        }
        board[i][j] = ch;  // 恢复现场（回溯）
        if (node->children.empty() && node->word.empty()) {
            parent->children.erase(ch);  // 剪枝：叶子被掏空后从父节点删除，Trie 越走越小
        }
    }
};

