// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n m（网格行数、列数）
//   接下来 n 行：每行一个长度为 m 的字符串（小写字母，无空格）
//   下一行：W（单词数）
//   接下来 W 行：每行一个单词
// 输出格式：找到的全部单词，每行一个，按字典序排序（没有则无输出）
#include <algorithm>
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

using namespace std;

// 字典树节点：children 键为字符；word 非空表示单词结尾，存完整单词便于收集
struct TrieNode {
    unordered_map<char, TrieNode*> children;
    string word;
};

int n, m;
vector<string> board;
vector<string> ans;

// 当前字符在 Trie 上无路可走时剪枝；命中单词即收集并清空防重复
void dfs(int i, int j, TrieNode* parent) {
    char ch = board[i][j];
    auto it = parent->children.find(ch);
    if (it == parent->children.end()) return;  // Trie 上无路可走，剪枝

    TrieNode* node = it->second;
    if (!node->word.empty()) {  // 命中即收集，清空防重复加入
        ans.push_back(node->word);
        node->word.clear();
    }
    board[i][j] = '#';  // 原地标记已访问
    const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (auto& d : dirs) {
        int x = i + d[0], y = j + d[1];
        if (x >= 0 && x < n && y >= 0 && y < m && board[x][y] != '#') {
            dfs(x, y, node);  // 四方向与 Trie 同步下行
        }
    }
    board[i][j] = ch;  // 恢复现场（回溯）
    if (node->children.empty() && node->word.empty()) {
        parent->children.erase(ch);  // 剪枝：掏空的叶子从父节点删除
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    board.resize(n);
    for (int i = 0; i < n; ++i) cin >> board[i];
    int w;
    cin >> w;
    TrieNode* root = new TrieNode();
    for (int i = 0; i < w; ++i) {  // 逐单词建 Trie
        string word;
        cin >> word;
        TrieNode* node = root;
        for (char ch : word) {
            if (!node->children.count(ch)) node->children[ch] = new TrieNode();
            node = node->children[ch];
        }
        node->word = word;  // 结尾存完整单词，命中即收集
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            dfs(i, j, root);  // 每个格子都尝试作为起点
        }
    }

    sort(ans.begin(), ans.end());  // 排序保证输出确定
    for (const string& word : ans) cout << word << '\n';
    return 0;
}

