var findWords = function (board, words) {
  const trie = new Map();  // 嵌套 Map 实现字典树：字符 -> 子节点
  for (const w of words) {
    let node = trie;
    for (const ch of w) {
      if (!node.has(ch)) node.set(ch, new Map());
      node = node.get(ch);
    }
    node.set('#', w);  // '#': 单词结尾，直接存完整单词便于收集
  }
