  const dfs = (i, j, parent) => {
    const ch = board[i][j];
    const node = parent.get(ch);
    if (node === undefined) return;  // 当前字符在 Trie 上无路可走，剪枝
    const word = node.get('#');      // 命中单词就收集；删掉防止同一单词重复加入
    if (word !== undefined) {
      ans.push(word);
      node.delete('#');
